       _waitingClock = waitingClock ?? DateTime.now,
       _waitingSleep =
           waitingSleep ?? ((Duration d) => Future<void>.delayed(d)),
       _useTui = useTui && io.supportsRawMode,
       sigintPolicy = sigintPolicy ?? SigintPolicy() {
