      pluginTools.addAll(context.tools);
      _pluginInboxes.addAll(context.externalInboxes);
      _pluginSlashCommands.addAll(context.slashCommands);
      _pluginSlashDescriptions.addAll(context.slashCommandDescriptions);
    }

