    ? HepWriter(
        emit: _writeHepLine,
        fahVersion: packageVersion,
        toolArgs: parsed.output == 'events=full'
            ? HepToolArgs.full
            : HepToolArgs.summary,
        redactionPipeline: redactionPipeline,
