      expect(await first.runHeadless('go'), 0);
      final sessions = await JsonlSessionRepo(
        fs: env,
        sessionsRoot: '/sessions',
      ).list();
      final sessionId = sessions.single.id;

      // Simulate a concurrent writer that already folded a LONGER chain
