      expect(await second.runHeadless('again'), 0);

      final after = await readLedger(sessionId);
      expect(after, isNotNull);
      expect(after!.chainRecords, concurrent.chainRecords);
      expect(after.chainHash, 'sha256:concurrent-writer');
    },
