import 'agent_cli_test_support.dart';

Usage reportedUsage({int input = 100, int output = 50}) => Usage(
  input: input,
  output: output,
  cacheRead: 0,
  cacheWrite: 0,
  totalTokens: input + output,
  cost: const UsageCost(),
);

