  // run log found nothing. Mirror the line to stdout in non-TUI
  // sessions — [CliIO.write] is the stdout channel (headless hosts route
  // writeln to stderr); structured modes wrap io in HepEventsIO, which
  // drops write, so the HEP/stream-json wires stay pure.
  if (!_useTui) io.write('$line\n');
}
