        fs: env,
        sessionsRoot: '/sessions',
      ).list();
      final sessionId = sessions.single.id;

      // Wreck the artifact (E3: hand-edited garbage).
      await env.writeFile(
        '/sessions/$sessionId/usage.json',
        '{"garbage":true}',
