    SigintPolicy? sigintPolicy,
  }) : io = useTui && io.supportsRawMode ? _TuiCliIO(io) : io,
       _style = _Style(enabled: useColor),
       _markdownSurface = markdownSurface ?? const MarkdownSurface(),
